INSERT INTO blog_post_translations
  (post_id, locale, slug, title, excerpt, body_html, seo_title, seo_description)
VALUES (
  :post_id, 'uz', $x$oyin-valyutasini-xavfsiz-sotib-olish$x$,
  $x$Oʻyin valyutasini qanday xavfsiz sotib olish mumkin$x$,
  $x$Firibgar sotuvchilarni qanday tanish, xizmatni bir daqiqada tekshirish, karta maʼlumotlarini himoya qilish va nega ID orqali toʻldirish paroldan xavfsizroq.$x$,
$x$<h2>Asosiysi</h2>
<ul>
<li>Xavfsiz xarid sotuvchini tekshirishdan boshlanadi: domen, kontaktlar, sharhlar va toʻlov usuli past narxdan muhimroq.</li>
<li>Avtomatik yetkazish qoʻlda sxemalarning asosiy xavfini yopadi: sotuvchi pul bilan gʻoyib boʻlmaydi va akkauntingizga kirishni soʻramaydi.</li>
<li>Oʻyin akkauntining login va parolini valyuta sotuvchisiga hech qachon bermang: qonuniy toʻldirish oʻyin ID orqali boʻladi.</li>
<li>Karta bilan toʻlaganda HTTPS, 3-D Secure tasdiqlash va PIN-kod kabi ortiqcha maʼlumot soʻralmasligini tekshiring.</li>
</ul>
<p>Xavfsiz xarid uchta oddiy tekshiruvga tayanadi: aniq kontaktli xizmatdan sotib olasiz, himoyalangan toʻlov sahifasi orqali toʻlaysiz va donatni oʻyin ID boʻyicha olasiz, login va parolni bermaysiz. Shulardan biri buzilsa, narx qanchalik jozibali boʻlmasin, xariddan voz keching.</p>
<h2>Nega donat xaridiga jiddiy qarash kerak</h2>
<p>Oʻyin platformalari firibgarlarning sevimli nishoniga aylangan. Kaspersky maʼlumotiga koʻra, 2025-yil yanvar-oktabr oylarida oʻyin platformalariga oid 20 milliondan ortiq hujum qayd etilgan (<a href="https://www.kaspersky.com/about/press-releases/kaspersky-reports-64-million-shopping-phishing-attempts-and-over-20-million-gaming-attacks-detected-in-2025">Kaspersky</a>). Geymer uchun bu oddiy narsani anglatadi: tez donat uchun karta maʼlumotlarini kiritayotgan sahifangiz soxta boʻlishi mumkin.</p>
<h2>Firibgar sayt va sotuvchilarning belgilari</h2>
<ul>
<li>Narx bozordan ancha past. PUBG Mobile uchun UC yoki Genshin Impact kristallari hamma joydagidan bir necha baravar arzon boʻlsa, bu foyda emas, xoʻrak.</li>
<li>Toʻlov faqat jismoniy shaxs kartasiga yoki kriptoda. Halol xizmat pulni toʻlov provayderlari orqali oladi, «doʻstga» oʻtkazma bilan emas.</li>
<li>Akkaunt login va parolini soʻrash. Qonuniy toʻldirish oʻyin ID orqali boʻladi. Akkauntga kirish firibgarga uni oʻgʻirlash yoki qimmat buyumlarni chiqarib olish uchun kerak.</li>
<li>Kontaktlar va yuridik maʼlumotlar yoʻq. Nom, ishlaydigan qoʻllab-quvvatlash va ochiq sharhlar boʻlmasa, bitim uchun javob beradigan hech kim yoʻq.</li>
<li>Bosim va shoshqaloqlik. «Aksiya faqat bugun», «ikkita joy qoldi», darhol toʻlash talabi — sunʼiy shoshilinchlik tekshirishga xalaqit beradi.</li>
<li>Xatoli sayt va gʻalati domen. Manzildagi xatolar, yangi domen, qiyshiq dizayn va HTTPS yoʻqligi shoshib yigʻilgan fishing sahifasini fosh qiladi.</li>
</ul>
<p>Oʻyinchilar oʻrtasida buyum va valyuta qayta sotiladigan tashqi maydonchalar alohida xavf: u yerda bitim kafolati yoʻq, xaridor birinchi marta koʻrgan sotuvchi bilan yolgʻiz qoladi.</p>
<h2>Nega avtomatlashtirish muhim</h2>
<p>Qoʻlda sxemalarning asosiy zaifligi — toʻlovingiz va donat olishingiz oʻrtasida odam turadi. U pulni olib gʻoyib boʻlishi, yetkazishni bir kunga choʻzishi yoki qoʻshimcha toʻlov talab qilishi mumkin. Avtomatlashtirish bu boʻgʻinni olib tashlaydi.</p>
<p>Avtomatik xizmatda jarayon shunday: oʻyin ID’ni koʻrsatasiz, toʻlaysiz, valyuta operator ishtirokisiz darhol tushadi. YuPay aynan shunday ishlaydi: ID’ni kiritasiz, «Tekshirish»ni bosib akkaunt topilganini koʻrasiz, Click, Payme yoki Uzum orqali toʻlaysiz, donat akkauntga avtomatik keladi. Soʻmdagi yakuniy summa toʻlovdan oldin koʻrinadi va aynan shu summa yechiladi.</p>
<p>Avtomatlashtirish ikkinchi muammoni ham hal qiladi: login va parolni berish shart emas. Toʻldirish ochiq oʻyin identifikatoriga bogʻlangan, akkauntga kirish esa faqat sizda qoladi. Toʻldirish qanday ishlashi haqida batafsil — <a href="/uz/blog/onlayn-oyin-toldirish">onlayn oʻyin toʻldirish</a> maqolasida.</p>
<h2>Xizmat ishonchliligini qanday tekshirish</h2>
<ul>
<li>Domen va himoyalangan ulanish: manzil HTTPS orqali, brauzer ogohlantirishisiz ochilsin; domen yozilishini harfma-harf solishtiring.</li>
<li>Kontaktlar: halol xizmatda nom, ishlaydigan qoʻllab-quvvatlash va ochiq oferta bor.</li>
<li>Toʻlov usullari: toʻlov provayderlari orqali soʻmdagi mahalliy usullar shaxsiy kartaga oʻtkazmadan ishonchliroq.</li>
<li>Yetkazish mexanikasi: toʻldirish uchun login va parol emas, oʻyin ID kerakligini aniqlang. Bu qonuniy xizmatning asosiy belgisi.</li>
<li>Sharhlar va tarix: saytdagi maqtovlar emas, tashqi maydonchalardagi yangi sharhlarni qidiring.</li>
</ul>
<p>Mahalliy sotuvchidan donat olish nega koʻpincha xorijiy vositachilardan foydaliroq va xavfsizroq — <a href="/uz/blog/donatni-mahalliy-sotib-olish">donatni mahalliy sotib olish nega foydali</a> maqolasida.</p>
<h2>Karta bilan toʻlashda maʼlumotlarni himoya qilish</h2>
<ul>
<li>Toʻlov sahifasi bank yoki toʻlov tizimiga tegishli boʻlsin, doʻkon sahifasidagi oʻzi yasalgan maydon emas.</li>
<li>3-D Secure tasdiqlash: bank ilovasi yoki SMS’dan bir martalik kod kartani sizdan bexabar ishlatilishidan himoya qiladi.</li>
<li>Faqat toʻlov maʼlumotlarini kiriting: karta raqami, amal qilish muddati va CVC. PIN-kod, onlayn-bank paroli va bank hech kimga aytmaslikni soʻragan kodlar hech kimga berilmaydi.</li>
<li>Kiritishdan oldin manzilni tekshiring: fishing mashhur saytlarning koʻrinishini koʻchiradi.</li>
<li>Limit va bildirishnomali karta ishlating: maʼlumotlar sizib chiqsa ham zarar cheklanadi.</li>
</ul>
<p>PCI DSS standarti toʻlov xizmatlaridan toʻlov sahifasini karta maʼlumotlarini oʻgʻirlaydigan skriptlardan himoya qilishni talab qiladi. Xaridor uchun bu rekvizitlarni oʻzi yigʻadigan emas, ishonchli provayder orqali toʻlov oʻtkazadigan xizmatlar foydasiga dalil.</p>
<h2>Xavfsiz donat xaridi uchun tekshiruv roʻyxati</h2>
<p>Har toʻlovdan oldin shu roʻyxatni koʻrib chiqing; birorta band bajarilmasa, toʻxtang.</p>
<ul>
<li>Domen HTTPS orqali ochiladi, yozilishi tekshirilgan.</li>
<li>Xizmatda nom, kontaktlar va ishlaydigan qoʻllab-quvvatlash bor.</li>
<li>Narx bozor doirasida, «haqiqat boʻlish uchun juda yaxshi» emas.</li>
<li>Toʻldirish uchun oʻyin ID kifoya, login va parol kerak emas.</li>
<li>Toʻlov shaxsiy kartaga emas, toʻlov provayderi orqali.</li>
<li>Toʻlov sahifasi himoyalangan, tranzaksiya 3-D Secure bilan tasdiqlanadi.</li>
<li>Faqat karta raqami, muddat va CVC kiritiladi, PIN va bank kodlari emas.</li>
<li>Kartada bildirishnomalar yoqilgan, iloji boʻlsa onlayn operatsiyalarga limit bor.</li>
</ul>
<p>Donat xaridi xavfsizligi deyarli toʻliq xizmat tanlovi va toʻlovdagi eʼtiborga bogʻliq. Avtomatik yetkazish va soʻmda toʻlovli bitta ishonchli xizmatni tanlang, xatcho‘plarga saqlang va faqat oʻsha yerdan xarid qiling.</p>$x$,
